export const ORDER_STATES = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"] as const;

export type OrderState = (typeof ORDER_STATES)[number];

const NEXT_STATE: Partial<Record<OrderState, OrderState>> = {
  placed: "paid",
  paid: "packed",
  packed: "shipped",
  shipped: "delivered",
};

const CANCELLABLE: readonly OrderState[] = ["placed", "paid", "packed"];

export function isOrderState(value: unknown): value is OrderState {
  return typeof value === "string" && (ORDER_STATES as readonly string[]).includes(value);
}

export function nextStateOf(state: OrderState): OrderState | undefined {
  return NEXT_STATE[state];
}

export function isCancellable(state: OrderState): boolean {
  return CANCELLABLE.includes(state);
}

